  face=0;pd_weapon_damage_parts parts;assert(pd_smite_damage(&s,&hit,0,slot,pact,fiend,rider>0,rng,NULL,&parts));assert(parts.smite.sides==8&&parts.smite.count==(dice>PD_POOL_MAX?PD_POOL_MAX:dice)&&parts.smite_overflow.count==(dice>PD_POOL_MAX?dice-PD_POOL_MAX:0)&&parts.smite.total+parts.smite_overflow.total==(int)dice&&parts.extra.count==(rider?(crit?2:1):0)&&parts.radiant.count==(cantrip?(crit?2:1):0));assert(parts.total==parts.weapon.total+parts.radiant.total+parts.extra.total+parts.smite.total+parts.smite_overflow.total&&calls==old+parts.weapon.count+parts.radiant.count+parts.extra.count+parts.smite.count+parts.smite_overflow.count&&!memcmp(&before,&s,sizeof s));
